template.solver:
def solve(N):
    M = 2*N + 2
    s = [True]*(M+1)
    s[0] = False
    s[1] = False
    for i in range(2, M+1):
        if s[i]:
            for j in range(i*i, M+1, i):
                s[j] = False
    best = 0
    for a in range(2, N):
        b = N - a
        if b >= 2 and s[a] and s[b]:
            for c in range(2, N):
                if s[c]:
                    t = [a, b, c, a+b-c, a+c-b, b+c-a, a+b+c]
                    if min(t) > 1 and len(set(t)) == 7:
                        ok = True
                        for x in t:
                            if not s[x]:
                                ok = False
                                break
                        if ok:
                            d = max(t) - min(t)
                            if d > best:
                                best = d
    return best
